  command: `node .harness/v7/loop/e2e.mjs ${output} ${duration} ${profile}`,
  startedAt: new Date().toISOString(), elapsedMs: 0, status: 'running', completion: 'running', checks: [], sessions: [], screenshots: [], errors: [],
  bootstrap: 'Production BrowserWindows, preload, renderer, IPC and save; harness lifecycle.',
